import { mapResponsiveStyles } from '@fiverr-private/theme';
const STYLES_BY_SIZE = {
  sm: {
    paddingY: '1.5',
    paddingX: '3',
    lineHeight: 'b_sm',
    fontSize: 'b_sm'
  },
  md: {
    paddingY: '2',
    paddingX: '4',
    lineHeight: 'b_md',
    fontSize: 'b_md'
  },
  lg: {
    paddingY: '2.5',
    paddingX: '5',
    lineHeight: 'b_lg',
    fontSize: 'b_md'
  }
};
export const getConditionalSize = size => {
  if (typeof size === 'object') {
    return {
      paddingX: mapResponsiveStyles(size, value => STYLES_BY_SIZE[value].paddingX),
      paddingY: mapResponsiveStyles(size, value => STYLES_BY_SIZE[value].paddingY),
      fontSize: mapResponsiveStyles(size, value => STYLES_BY_SIZE[value].fontSize),
      lineHeight: mapResponsiveStyles(size, value => STYLES_BY_SIZE[value].lineHeight)
    };
  }
  return STYLES_BY_SIZE[size || 'md'];
};
export const getConditionalFullWidth = fullWidth => {
  if (typeof fullWidth === 'object') {
    return mapResponsiveStyles(fullWidth, value => value ? '100%' : 'initial');
  }
  return fullWidth ? '100%' : undefined;
};